# -*- coding: utf-8 -*-
"""
80 unique B2 railway dialogues (Railway Academy & Technical BDZ/NRIC operations).
Authentic technical terminology:
- accurate Bulgarian grammar ('във', 'със', clitic rules)
- realistic operational communications (ДСП, ДНЦ, машинист, ревизор, маневрист)
- factual railway terms without claiming official normative approval
"""

dialogues_b2 = []

def d(did, title, topic, lines_tuples, question, answer, alts=None):
    parsed = [{"speaker": s, "bg": bg, "ru": ru} for s, bg, ru in lines_tuples]
    assert any(answer in p["bg"] for p in parsed), f"Answer '{answer}' not found in {did}"
    dialogues_b2.append({
        "id": did,
        "level": "B2",
        "title": title,
        "topic": topic,
        "lines": parsed,
        "question": question,
        "answer": answer,
        "alternatives": alts or []
    })

